INSERT INTO users (handle, name, headline, bio, teach_style, city, country, tz_offset, main_field, meets_online, meets_in_person, github, member_no, joined_on, is_sample, likes_newcomers, prior_taught, prior_learned, prior_rating, reply_time) VALUES
  ('samokoye', 'Sam Okoye', 'Java and Spring backend developer', 'I build payment APIs in Java all day. My Git history is a crime scene, and I would love someone to finally explain rebase to me.', 'Live coding on a real repo, then a small exercise for next time.', 'Lagos', 'Nigeria', 1, 'backend', TRUE, FALSE, 'samokoye', '0101', '2026-03-01', TRUE, TRUE, 14, 9, 4.9, '2 hours'),
  ('minapark', 'Mina Park', 'React engineer at a design studio', 'Frontend person who cares about the last 10% of polish. I want to stop asking designers for every icon and learn Figma properly.', 'Pair programming. You drive, I navigate.', 'Seoul', 'South Korea', 9, 'frontend', TRUE, FALSE, 'minapark', '0138', '2026-01-01', TRUE, TRUE, 21, 6, 4.8, '1 hour'),
  ('diegoplays', 'Diego Alvarez', 'Indie game developer in Unity', 'Shipped two small games on Steam. I can teach you Unity from an empty scene to a playable build. My UI looks like 2004, so I need design help.', 'We build one tiny game mechanic per session.', 'Valencia', 'Spain', 1, 'gamedev', TRUE, FALSE, 'diegoplays', '0175', '2026-04-01', TRUE, TRUE, 8, 5, 5, '3 hours'),
  ('hanaops', 'Hana Yusuf', 'Platform engineer, cloud and containers', 'I keep 200 services running on Kubernetes. Outside work I want to build my own product, which means learning React and some design.', 'Hands-on labs. You break a cluster, then we fix it together.', 'Erbil', 'Iraq', 3, 'devops', TRUE, TRUE, 'hanaops', '0212', '2026-02-01', TRUE, FALSE, 17, 4, 4.9, '4 hours'),
  ('lucasmotion', 'Lucas Ferreira', 'Motion designer for product launches', 'I animate launch videos and UI motion. I want to script After Effects with code instead of clicking the same 40 keyframes every day.', 'We recreate a real shot from a launch video, step by step.', 'São Paulo', 'Brazil', -3, 'motion', TRUE, FALSE, NULL, '0249', '2026-05-01', TRUE, FALSE, 11, 3, 4.7, '6 hours'),
  ('aishadata', 'Aisha Rahman', 'Machine learning engineer', 'I train vision models for a health startup. I want to build demos people can click, so I need React, Docker and a bit of design taste.', 'Notebook walkthroughs with real datasets.', 'Dhaka', 'Bangladesh', 6, 'ml', TRUE, FALSE, 'aishadata', '0286', '2026-01-01', TRUE, FALSE, 19, 7, 4.9, '2 hours'),
  ('tomasfs', 'Tomáš Novák', 'Full-stack developer, TypeScript everywhere', 'I build SaaS products end to end with Node and React. Rust is my next big thing, and I keep hearing Kubernetes is unavoidable.', 'Code review style: you bring your code, we improve it together.', 'Prague', 'Czechia', 1, 'fullstack', TRUE, TRUE, 'tomasfs', '0323', '2025-12-01', TRUE, FALSE, 26, 10, 4.8, '1 hour'),
  ('yukiux', 'Yuki Tanaka', 'Product designer, design systems', 'I design apps for a fintech company. I want to read the code my designs turn into, and maybe build my own portfolio site.', 'Critique sessions on your actual screens.', 'Osaka', 'Japan', 9, 'uiux', TRUE, FALSE, NULL, '0360', '2026-02-01', TRUE, FALSE, 15, 8, 5, '2 hours'),
  ('omarsec', 'Omar Khalil', 'Penetration tester', 'I break into web apps for a living, legally. I want to write my own tools in Go and understand the frameworks I keep attacking.', 'Capture-the-flag style challenges, explained afterwards.', 'Amman', 'Jordan', 3, 'security', TRUE, FALSE, 'omarsec', '0397', '2026-04-01', TRUE, FALSE, 9, 6, 4.8, '5 hours'),
  ('priyabuilds', 'Priya Nair', 'Flutter developer', 'I build cross-platform apps for small businesses. Clients keep asking for native iOS features, so Swift is next on my list.', 'We build one screen of a real app together.', 'Bengaluru', 'India', 5.5, 'mobile', TRUE, FALSE, 'priyabuilds', '0434', '2026-03-01', TRUE, TRUE, 12, 5, 4.9, '2 hours'),
  ('jonasiot', 'Jonas Weber', 'Firmware engineer, sensors and robots', 'I write firmware for industrial sensors. I want to build dashboards for my devices and test my data with Python.', 'Bring a board. We blink an LED and keep going from there.', 'Munich', 'Germany', 1, 'embedded', TRUE, TRUE, 'jonasiot', '0471', '2026-05-01', TRUE, FALSE, 7, 3, 4.8, '8 hours'),
  ('fatimaqa', 'Fatima Zahra', 'QA automation engineer', 'I automate end-to-end tests for an e-commerce site. I want to run my test suites in containers and understand the code I test better.', 'We write tests for your own project.', 'Casablanca', 'Morocco', 1, 'qa', TRUE, FALSE, 'fatimaqa', '0508', '2026-04-01', TRUE, FALSE, 10, 4, 4.7, '3 hours'),
  ('elifcodes', 'Elif Demir', 'Go backend developer', 'I build high-traffic APIs in Go. I want to learn Rust for fun and get better at sketching ideas before I code them.', 'Short theory, long practice. Lots of small exercises.', 'Istanbul', 'Türkiye', 3, 'backend', TRUE, FALSE, 'elifcodes', '0545', '2026-02-01', TRUE, TRUE, 13, 6, 4.8, '2 hours'),
  ('noahdraws', 'Noah Kim', 'Technical artist for games', 'I make 3D assets and shaders for a mid-size studio. I want to write Python tools for Blender and understand engine C++.', 'Screen share in Blender. You copy each step.', 'Vancouver', 'Canada', -8, '3d', TRUE, FALSE, NULL, '0582', '2026-01-01', TRUE, FALSE, 16, 5, 4.9, '4 hours'),
  ('zaraahmed', 'Zara Ahmed', 'iOS developer', 'I build iOS apps for a delivery company. I want to cover Android too and stop shipping two separate codebases.', 'We read Apple sample code together, then rebuild it.', 'Dubai', 'UAE', 4, 'mobile', TRUE, TRUE, 'zaraahmed', '0619', '2026-03-01', TRUE, FALSE, 12, 4, 4.8, '3 hours'),
  ('mateovue', 'Mateo Rossi', 'Vue and Nuxt developer', 'Freelance frontend developer. I write a lot of CSS and I love it. I want to automate my deployment with Docker and some Python.', 'We rebuild a real landing page from scratch.', 'Milan', 'Italy', 1, 'frontend', TRUE, TRUE, 'mateovue', '0656', '2025-12-01', TRUE, FALSE, 18, 3, 4.7, '1 hour'),
  ('chloemartin', 'Chloé Martin', 'UI motion and Lottie animator', 'I make micro-animations for apps. I want to code interactive 3D on the web instead of exporting videos.', 'We animate one interaction from storyboard to export.', 'Lyon', 'France', 1, 'motion', TRUE, FALSE, NULL, '0693', '2026-04-01', TRUE, FALSE, 9, 4, 4.9, '5 hours'),
  ('kwamecloud', 'Kwame Mensah', 'Site reliability engineer', 'I run infrastructure for a fintech. I want to write proper tools in Go and Python instead of 500-line Bash scripts.', 'Incident drills: something breaks, we debug it together.', 'Accra', 'Ghana', 0, 'devops', TRUE, FALSE, 'kwamecloud', '0730', '2026-01-01', TRUE, FALSE, 20, 7, 4.8, '2 hours'),
  ('leafullstack', 'Lea Schmidt', 'Laravel and Vue developer', 'I build booking systems for hotels with Laravel. I want modern tooling: TypeScript, containers and a cleaner Git workflow.', 'We add one real feature to an app, from route to view.', 'Vienna', 'Austria', 1, 'fullstack', TRUE, TRUE, 'leafullstack', '0767', '2026-02-01', TRUE, FALSE, 14, 5, 4.7, '3 hours'),
  ('arjunmehta', 'Arjun Mehta', 'Data analyst moving into ML', 'I write SQL all day for a retail company. I want to move into machine learning and stop emailing CSV files around.', 'We answer a real business question with data.', 'Pune', 'India', 5.5, 'dataanalysis', TRUE, FALSE, 'arjunmehta', '0804', '2026-03-01', TRUE, TRUE, 11, 9, 4.8, '2 hours'),
  ('sofiajava', 'Sofia Petrova', 'Android developer, Java and Kotlin', 'Eight years of Java, three of Kotlin on Android. I love teaching Java basics properly. I want Python for side projects and better Git habits.', 'Whiteboard first, then we code it together.', 'Sofia', 'Bulgaria', 2, 'mobile', TRUE, FALSE, 'sofiajava', '0841', '2025-12-01', TRUE, TRUE, 22, 6, 5, '1 hour'),
  ('ivocosta', 'Ivo Costa', 'Godot developer and game jam regular', 'I make small weird games, mostly in Godot, sometimes Unity. I want to model my own 3D assets and stop buying asset packs.', 'Game jam pace: build something playable in one session.', 'Lisbon', 'Portugal', 0, 'gamedev', TRUE, FALSE, 'ivocosta', '0878', '2026-02-01', TRUE, FALSE, 10, 8, 4.9, '3 hours'),
  ('nadiahaddad', 'Nadia Haddad', 'Security analyst', 'I hunt vulnerabilities in web apps and write the reports nobody wants to read. I want to understand cloud setups I keep auditing.', 'We audit a deliberately broken app together.', 'Beirut', 'Lebanon', 2, 'security', TRUE, FALSE, 'nadiahaddad', '0915', '2026-04-01', TRUE, FALSE, 8, 5, 4.8, '4 hours'),
  ('benjcarter', 'Ben Carter', 'Software developer in test', 'I build test frameworks in Python. I want to write UI tests for React apps and understand what I am actually testing.', 'We write a failing test, then make it pass.', 'Manchester', 'United Kingdom', 0, 'qa', TRUE, TRUE, 'benjcarter', '0952', '2026-01-01', TRUE, FALSE, 12, 6, 4.7, '3 hours'),
  ('laylareact', 'Layla Aziz', 'MERN stack developer', 'I build web apps with React, Node and MongoDB for local businesses. I want to get better at SQL, design and Python scripting.', 'Build-along sessions: we ship one feature end to end.', 'Sulaymaniyah', 'Iraq', 3, 'fullstack', TRUE, TRUE, 'laylareact', '0989', '2026-02-01', TRUE, TRUE, 13, 7, 4.9, '1 hour'),
  ('renito', 'Ren Ito', 'Robotics engineer', 'I build vision-guided robot arms. I want to try Rust for firmware and make simulations in Unity.', 'Real hardware on camera, explained slowly.', 'Tokyo', 'Japan', 9, 'embedded', TRUE, FALSE, 'renito', '1026', '2026-05-01', TRUE, FALSE, 9, 4, 4.8, '6 hours'),
  ('danarashid', 'Dana Rashid', 'Debate coach and public speaking trainer', 'I coach university debate teams and run speaking workshops. I want to automate my training plans with Python and make slides that do not look like 2009.', 'Short talks on camera, then honest feedback line by line.', 'Erbil', 'Iraq', 3, 'publicspeaking', TRUE, TRUE, NULL, '1063', '2026-01-01', TRUE, TRUE, 34, 7, 4.9, '1 hour'),
  ('karimvisuals', 'Karim Nassar', 'Video editor for YouTube channels', 'I edit long-form YouTube videos for three channels. I want to script my exports in Python and add proper motion titles.', 'We cut a real 60-second clip together, start to finish.', 'Cairo', 'Egypt', 2, 'videoediting', TRUE, FALSE, NULL, '1100', '2026-03-01', TRUE, TRUE, 19, 4, 4.8, '2 hours'),
  ('ellabrooks', 'Ella Brooks', 'Portrait and product photographer', 'I shoot portraits and products for small brands. I want a proper portfolio site and to stop guessing my prices.', 'Bring your camera or phone. We shoot, then edit together.', 'Toronto', 'Canada', -5, 'photography', TRUE, TRUE, NULL, '1137', '2026-02-01', TRUE, FALSE, 22, 5, 4.9, '3 hours'),
  ('linabarzani', 'Lina Barzani', 'Documentary videographer', 'I film short documentaries about mountain villages. I want to write better scripts and grade my footage like a pro.', 'Field sessions: we plan a shot list, then film it.', 'Duhok', 'Iraq', 3, 'videography', TRUE, TRUE, NULL, '1174', '2026-04-01', TRUE, FALSE, 12, 6, 4.8, '4 hours'),
  ('tariqmansour', 'Tariq Mansour', 'Music producer and mixing engineer', 'I produce Arabic pop and mix podcasts. I want to build small audio tools in Python and promote my releases better.', 'We mix one real song together, track by track.', 'Amman', 'Jordan', 3, 'audio', TRUE, FALSE, NULL, '1211', '2026-02-01', TRUE, FALSE, 16, 3, 4.8, '5 hours'),
  ('saralindqvist', 'Sara Lindqvist', 'Engineering manager', 'I lead a team of nine engineers. I teach the leadership basics I wish someone had taught me, and I want to learn Arabic for my team in Amman.', 'Real scenarios: you bring a situation, we role-play it.', 'Stockholm', 'Sweden', 1, 'leadership', TRUE, FALSE, NULL, '1248', '2025-12-01', TRUE, FALSE, 27, 4, 5, '2 hours'),
  ('ahmedsaleh', 'Ahmed Saleh', 'HR specialist and interview coach', 'I hire people for a telecom company and coach graduates for interviews. I want to query our HR data myself instead of waiting for IT.', 'Mock interviews, recorded and reviewed together.', 'Baghdad', 'Iraq', 3, 'communication', TRUE, TRUE, NULL, '1285', '2026-01-01', TRUE, FALSE, 23, 5, 4.8, '2 hours'),
  ('isabelmoreno', 'Isabel Moreno', 'Sales lead at a SaaS startup', 'I close deals for a startup and teach Spanish on the side. I want to pull my own sales numbers with SQL and Python.', 'We role-play a real negotiation, then break it down.', 'Madrid', 'Spain', 1, 'negotiation', TRUE, FALSE, NULL, '1322', '2026-03-01', TRUE, FALSE, 18, 6, 4.7, '3 hours'),
  ('bilalahmadi', 'Bilal Ahmadi', 'Math teacher and tutor', 'I teach high-school math and tutor university calculus. I want to show students simulations in Python instead of chalk drawings.', 'One problem, solved three different ways.', 'Mashhad', 'Iran', 3.5, 'math', TRUE, FALSE, NULL, '1359', '2026-01-01', TRUE, FALSE, 30, 4, 4.9, '2 hours'),
  ('nourelsayed', 'Nour El-Sayed', 'Digital marketer for small brands', 'I run SEO and ads for local shops. I want to make my own short video ads instead of paying an editor every week.', 'We audit your real website or page together.', 'Alexandria', 'Egypt', 2, 'marketing', TRUE, FALSE, NULL, '1396', '2026-02-01', TRUE, FALSE, 15, 6, 4.7, '2 hours'),
  ('leomartins', 'Leo Martins', 'Travel content creator', 'I make short videos about cheap travel for 200k followers. I want to speak on camera with real confidence and handle my brand-deal money properly.', 'We plan, film and post one short together.', 'Porto', 'Portugal', 0, 'socialmedia', TRUE, FALSE, NULL, '1433', '2026-02-01', TRUE, FALSE, 14, 9, 4.8, '1 hour'),
  ('amirasaeed', 'Amira Saeed', 'Founder of a meal-delivery startup', 'I started a meal-delivery service from my kitchen. Now I want to build our own app and understand our data.', 'We work on your real idea, one canvas at a time.', 'Riyadh', 'Saudi Arabia', 3, 'entrepreneurship', TRUE, FALSE, NULL, '1470', '2026-03-01', TRUE, FALSE, 11, 5, 4.8, '3 hours'),
  ('danielwu', 'Daniel Wu', 'Accountant and personal finance nerd', 'I audit companies by day and teach budgeting to friends by night. I want to automate reconciliations and speak at finance meetups.', 'Real spreadsheets, real numbers, no jargon.', 'Singapore', 'Singapore', 8, 'finance', TRUE, FALSE, NULL, '1507', '2026-01-01', TRUE, FALSE, 21, 4, 4.9, '2 hours'),
  ('graceokafor', 'Grace Okafor', 'Copywriter and editor', 'I write landing pages and edit books. I want to write inside design files and understand the HTML my words end up in.', 'We rewrite one real page of yours together.', 'Nairobi', 'Kenya', 3, 'writing', TRUE, FALSE, NULL, '1544', '2026-02-01', TRUE, FALSE, 20, 6, 4.9, '2 hours'),
  ('rezakarimi', 'Reza Karimi', 'PhD researcher in public health', 'I write papers about air pollution and health. I want to clean my survey data with Python and stop fighting Excel.', 'We take one chapter or paper and improve it together.', 'Tehran', 'Iran', 3.5, 'academic', TRUE, FALSE, NULL, '1581', '2026-03-01', TRUE, FALSE, 13, 8, 4.8, '4 hours'),
  ('hyejinlee', 'Hyejin Lee', 'Korean tutor and subtitle translator', 'I translate drama subtitles and tutor Korean. I want to sound natural in English meetings and edit my own lesson videos.', 'Conversation first, grammar when it comes up.', 'Busan', 'South Korea', 9, 'languages', TRUE, FALSE, NULL, '1618', '2025-12-01', TRUE, FALSE, 26, 7, 5, '1 hour'),
  ('mehmetyilmaz', 'Mehmet Yılmaz', 'Turkish teacher and home cook', 'I teach Turkish to newcomers and cook for everyone in my building. I want to learn Kurdish so I can talk with my neighbours properly.', 'We speak Turkish while we cook something real.', 'Izmir', 'Türkiye', 3, 'languages', TRUE, TRUE, NULL, '1655', '2026-02-01', TRUE, FALSE, 17, 3, 4.9, '3 hours'),
  ('emmalaurent', 'Emma Laurent', 'Screenwriter for short films', 'I write short films and teach French at weekends. I want to shoot and cut my own shorts instead of waiting for a crew.', 'We break down a scene, then rewrite it.', 'Paris', 'France', 1, 'storytelling', TRUE, TRUE, NULL, '1692', '2026-03-01', TRUE, FALSE, 16, 6, 4.8, '2 hours'),
  ('alirasul', 'Ali Rasul', 'Physics student and olympiad coach', 'I coach high-school physics olympiad teams and help with SAT math. I want to simulate experiments in Python and keep my code in Git.', 'We solve hard problems together on a shared whiteboard.', 'Sulaymaniyah', 'Iraq', 3, 'physics', TRUE, TRUE, NULL, '1729', '2026-04-01', TRUE, FALSE, 12, 5, 4.9, '2 hours'),
  ('zeynepkaya', 'Zeynep Kaya', 'Medical student', 'Fourth-year medical student. My note system got me through anatomy. I want to analyse lab results and learn statistics properly.', 'Active recall: I quiz you, you quiz me.', 'Ankara', 'Türkiye', 3, 'biology', TRUE, FALSE, NULL, '1766', '2026-03-01', TRUE, FALSE, 14, 6, 4.8, '3 hours'),
  ('oliviahart', 'Olivia Hart', 'IELTS examiner and English teacher', 'I prepare students for IELTS and TOEFL. Many of them are from Kurdistan, so I would love to greet them properly in Kurdish.', 'Timed practice, then a clear band-score breakdown.', 'Manchester', 'United Kingdom', 0, 'examprep', TRUE, FALSE, NULL, '1803', '2025-12-01', TRUE, TRUE, 38, 3, 5, '1 hour'),
  ('marcobianchi', 'Marco Bianchi', 'Guitar and piano teacher', 'I teach guitar and piano and sing in a small band. I want a simple website for my lessons and better photos of my gigs.', 'One song per session, played from day one.', 'Bologna', 'Italy', 1, 'music', TRUE, TRUE, NULL, '1840', '2026-01-01', TRUE, FALSE, 29, 4, 4.9, '2 hours'),
  ('rawaothman', 'Rawa Othman', 'Personal trainer and football coach', 'I coach a youth football team and train clients at a gym. I want to track client progress in spreadsheets and coach international clients in better English.', 'A short demo, then you do it while I correct your form.', 'Erbil', 'Iraq', 3, 'fitness', TRUE, TRUE, NULL, '1877', '2026-02-01', TRUE, FALSE, 24, 3, 4.8, '1 hour'),
  ('leilanavabi', 'Leila Navabi', 'Yoga teacher and mindfulness coach', 'I teach yoga and help students handle exam stress. I want to grow my classes online and take better photos of them.', 'Ten minutes of practice, then we talk about what changed.', 'Shiraz', 'Iran', 3.5, 'wellbeing', TRUE, FALSE, NULL, '1914', '2026-01-01', TRUE, FALSE, 22, 5, 5, '2 hours'),
  ('kaischneider', 'Kai Schneider', 'IT support lead', 'I keep 400 laptops and a dozen servers alive for a hospital. I want to automate user setup with Python and finally put my scripts in Git.', 'We build a small network in a simulator together.', 'Berlin', 'Germany', 1, 'networking', TRUE, FALSE, NULL, '1951', '2026-02-01', TRUE, FALSE, 18, 5, 4.8, '3 hours'),
  ('valentinacruz', 'Valentina Cruz', 'Illustrator and comic artist', 'I draw a weekly web comic and illustrate children’s books. I want to design an app for my comics and animate my characters.', 'We draw together on a shared canvas, live.', 'Mexico City', 'Mexico', -6, 'illustration', TRUE, FALSE, NULL, '1988', '2026-03-01', TRUE, FALSE, 20, 4, 4.9, '2 hours'),
  ('hibaalamin', 'Hiba Al-Amin', 'Architect and interior designer', 'I design homes and small cafés. I want to render my projects in Blender and photograph finished spaces myself.', 'We draw one real floor plan together.', 'Muscat', 'Oman', 4, 'cad', TRUE, TRUE, NULL, '2025', '2026-04-01', TRUE, FALSE, 15, 5, 4.8, '3 hours'),
  ('elenasokolova', 'Elena Sokolova', 'AI engineer building LLM apps', 'I build LLM-powered tools for a legal-tech startup. I want to present at AI meetups without my voice shaking, and design better demos.', 'We build a tiny AI tool together, live.', 'Tbilisi', 'Georgia', 4, 'ai', TRUE, FALSE, NULL, '2062', '2026-03-01', TRUE, FALSE, 17, 5, 4.9, '2 hours');
