INSERT INTO reviews (author_id, subject_id, skill_id, body) VALUES
  (pg_temp.uid('minapark'), pg_temp.uid('samokoye'), 'java', 'Sam drew the whole Spring request flow on a whiteboard. Finally understood dependency injection.'),
  (pg_temp.uid('samokoye'), pg_temp.uid('minapark'), 'react', 'Mina explains hooks with tiny examples that actually stick.'),
  (pg_temp.uid('ivocosta'), pg_temp.uid('diegoplays'), 'unity', 'Diego got my character controller working in under an hour.'),
  (pg_temp.uid('tomasfs'), pg_temp.uid('hanaops'), 'docker', 'Hana made Docker networking make sense. Patient and very clear.'),
  (pg_temp.uid('chloemartin'), pg_temp.uid('lucasmotion'), 'aftereffects', 'Lucas showed me graph editor tricks I had missed for years.'),
  (pg_temp.uid('arjunmehta'), pg_temp.uid('aishadata'), 'pandas', 'Aisha cleaned a messy dataset with me live. I learned more than in a whole course.'),
  (pg_temp.uid('hanaops'), pg_temp.uid('tomasfs'), 'nodejs', 'Tomáš helped me structure my first Express API. Super practical.'),
  (pg_temp.uid('minapark'), pg_temp.uid('yukiux'), 'figma', 'Yuki taught me auto layout properly. My components finally behave.'),
  (pg_temp.uid('nadiahaddad'), pg_temp.uid('omarsec'), 'burp', 'Omar walked me through my first real SQL injection. Clear and careful.'),
  (pg_temp.uid('zaraahmed'), pg_temp.uid('priyabuilds'), 'flutter', 'Priya made Flutter state management click for me.'),
  (pg_temp.uid('benjcarter'), pg_temp.uid('fatimaqa'), 'playwright', 'Fatima showed me how to make flaky tests stable. Life-changing.'),
  (pg_temp.uid('omarsec'), pg_temp.uid('elifcodes'), 'go', 'Elif taught me Go concurrency with clear drawings and tiny programs.'),
  (pg_temp.uid('ivocosta'), pg_temp.uid('noahdraws'), 'blender', 'Noah taught me retopology without making me feel slow.'),
  (pg_temp.uid('priyabuilds'), pg_temp.uid('zaraahmed'), 'swift', 'Zara explained SwiftUI previews and state in one evening.'),
  (pg_temp.uid('yukiux'), pg_temp.uid('mateovue'), 'css', 'Mateo finally made CSS grid make sense to me.'),
  (pg_temp.uid('lucasmotion'), pg_temp.uid('chloemartin'), 'lottie', 'Chloé knows every Lottie export trap. Saved me days.'),
  (pg_temp.uid('fatimaqa'), pg_temp.uid('kwamecloud'), 'ghactions', 'Kwame built a CI pipeline with me in one sitting.'),
  (pg_temp.uid('aishadata'), pg_temp.uid('arjunmehta'), 'sql', 'Arjun writes the cleanest window functions I have seen.'),
  (pg_temp.uid('zaraahmed'), pg_temp.uid('sofiajava'), 'kotlin', 'Sofia is the best Java teacher I have had. Clear and patient.'),
  (pg_temp.uid('diegoplays'), pg_temp.uid('ivocosta'), 'godot', 'Ivo got me shipping a jam game in Godot on my first weekend.'),
  (pg_temp.uid('omarsec'), pg_temp.uid('nadiahaddad'), 'wireshark', 'Nadia reads packet captures like a book.'),
  (pg_temp.uid('fatimaqa'), pg_temp.uid('benjcarter'), 'pytest', 'Ben showed me fixtures properly. My tests got half as long.'),
  (pg_temp.uid('hanaops'), pg_temp.uid('laylareact'), 'react', 'Layla taught me React by building my actual side project with me.'),
  (pg_temp.uid('jonasiot'), pg_temp.uid('renito'), 'opencv', 'Ren made OpenCV feel easy with a webcam and ten lines of code.'),
  (pg_temp.uid('leomartins'), pg_temp.uid('danarashid'), 'publicspeaking', 'Dana made me rehearse my intro ten times. My first conference talk went fine because of it.'),
  (pg_temp.uid('leomartins'), pg_temp.uid('karimvisuals'), 'capcut', 'Karim showed me J and L cuts. My videos finally flow.'),
  (pg_temp.uid('hibaalamin'), pg_temp.uid('ellabrooks'), 'productphoto', 'Ella taught me to light a model with one lamp and a white card.'),
  (pg_temp.uid('emmalaurent'), pg_temp.uid('linabarzani'), 'filmmaking', 'Lina planned my first short with me, shot by shot.'),
  (pg_temp.uid('kwamecloud'), pg_temp.uid('saralindqvist'), 'feedback', 'Sara’s feedback framework changed how I run one-on-ones.'),
  (pg_temp.uid('zeynepkaya'), pg_temp.uid('bilalahmadi'), 'calculus', 'Bilal explained integrals with a water tank drawing. I will never forget it.'),
  (pg_temp.uid('nourelsayed'), pg_temp.uid('leomartins'), 'shortvideo', 'Leo showed me hooks that keep people watching past three seconds.'),
  (pg_temp.uid('leomartins'), pg_temp.uid('danielwu'), 'budgeting', 'Daniel set up a budget with me that I actually stick to.'),
  (pg_temp.uid('oliviahart'), pg_temp.uid('hyejinlee'), 'korean', 'Hyejin got me ordering food in Korean after two sessions.'),
  (pg_temp.uid('linabarzani'), pg_temp.uid('emmalaurent'), 'scriptwriting', 'Emma turned my messy interview notes into a real story structure.'),
  (pg_temp.uid('hyejinlee'), pg_temp.uid('oliviahart'), 'english', 'Olivia found the same three mistakes in every sentence I wrote, and fixed them kindly.'),
  (pg_temp.uid('chloemartin'), pg_temp.uid('valentinacruz'), 'characterdesign', 'Valentina taught me to build characters from simple shapes first.');
INSERT INTO lessons (user_id, skill_id, title, tried, why_failed, learned, visibility, happened_on) VALUES
  (pg_temp.uid('danarashid'), 'publicspeaking', 'Memorised every word', 'I memorised my first competition speech word for word.', 'I lost one line and froze for twenty seconds.', 'Memorise the structure, not the sentences.', 'public', '2015-04-01'),
  (pg_temp.uid('ellabrooks'), 'photobasics', 'Shot a wedding on auto', 'I shot my first paid wedding fully on auto mode.', 'Half the indoor photos came out orange and blurry.', 'Learn manual exposure before you take money for it.', 'public', '2015-08-01'),
  (pg_temp.uid('saralindqvist'), 'teamleadership', 'Did every task myself', 'In my first lead role I took every hard ticket myself.', 'The team stopped growing and I burned out in four months.', 'Delegate the interesting work, not just the boring work.', 'public', '2014-11-01');
