INSERT INTO lessons (user_id, skill_id, title, tried, why_failed, learned, visibility, happened_on) VALUES
  (pg_temp.uid('arinavarro'), 'python', 'Six tutorials at once', 'I started six Python courses in the same week.', 'I finished none of them. Switching felt like progress, but nothing stuck.', 'One source, one partner, one small project.', 'private', '2026-06-10'),
  (pg_temp.uid('arinavarro'), 'git', 'Force-pushed to main', 'I force-pushed my branch to clean up history right before a deadline.', 'It wiped two days of my teammate’s commits.', 'Never rewrite shared history. Revert, or ask first.', 'public', '2026-07-22'),
  (pg_temp.uid('arinavarro'), 'publicspeaking', 'Read my slides out loud', 'I presented my course project by reading every slide.', 'People stopped listening after the second slide.', 'Slides are for the audience. Notes are for me.', 'private', '2026-10-29');
